package com.feurstagram.patches.ui

import app.morphe.patcher.patch.resourcePatch
import app.morphe.util.ResourceGroup
import app.morphe.util.asSequence
import app.morphe.util.copyResources
import com.feurstagram.patches.shared.Constants.COMPATIBILITY_INSTAGRAM
import org.w3c.dom.Element

private const val ICON = "@mipmap/oxbow_ic_launcher"

// Resources are generated by brand/build.py; edit the geometry there, not the XML.
@Suppress("unused")
val iconPatch = resourcePatch(
    name = "Oxbow icon",
    description = "Replaces the launcher icon with the Oxbow mark (adaptive, with a " +
        "monochrome layer for themed icons).",
    default = true,
) {
    compatibleWith(COMPATIBILITY_INSTAGRAM)

    execute {
        copyResources(
            "oxbow-icon",
            ResourceGroup(
                "drawable",
                "oxbow_ic_launcher_background.xml",
                "oxbow_ic_launcher_foreground.xml",
                "oxbow_ic_launcher_monochrome.xml",
            ),
            ResourceGroup("mipmap-anydpi-v26", "oxbow_ic_launcher.xml"),
        )

        document("AndroidManifest.xml").use { document ->
            val application = document.getElementsByTagName("application").item(0) as Element
            // Instagram ships one launcher alias per alternate app icon; whichever is
            // enabled must show ours. Activities (the lock-screen camera) keep their own.
            document.getElementsByTagName("activity-alias").asSequence().map { it as Element }
                .forEach { alias ->
                    if (alias.hasAttribute("android:icon")) alias.setAttribute("android:icon", ICON)
                    if (alias.hasAttribute("android:roundIcon")) alias.setAttribute("android:roundIcon", ICON)
                }
            application.setAttribute("android:icon", ICON)
            application.setAttribute("android:roundIcon", ICON)
        }
    }
}
